def calculate_a(n_limit):
    a = [0] * (n_limit + 1)
    a[1] = 0
    for n in range(2, n_limit + 1):
        max_val = -float('inf')
        for i in range(1, n):
            val = a[i] + a[n-i] + min(i, n-i)
            if val > max_val:
                max_val = val
        a[n] = max_val
    return a

n_limit = 100
a = calculate_a(n_limit)
for i in range(1, n_limit + 1):
    print(f"a({i}) = {a[i]}")
